import 'dart:convert';
import 'dart:typed_data';

import 'package:freezed_annotation/freezed_annotation.dart';

// required: associates our `image_data.dart` with the code generated by Freezed
part 'image_data.freezed.dart';
// optional: Since our Image class is serializable, we must add this line.
// But if Image was not serializable, we could skip it.
part 'image_data.g.dart';

