// Convert Base64 to Uint8List
Uint8List? _fromBase64(String? base64String) {
  if (base64String == null) return null;
  return base64Decode(base64String);
}

// Convert Uint8List to Base64 String
String? _toBase64(Uint8List? bytes) {
  if (bytes == null) return null;
  return base64Encode(bytes);
}

/* To create the data model or to apply changes in the data model or there's modification in the method for @JsonKey(),
execute this command in terminal: dart run build_runner build --delete-conflicting-outputs*/

// Model for a Single ImageData
@freezed
class ImageData with _$ImageData {
  // not sure if it useful yet
  factory ImageData({
    @JsonKey(name: "img_id") String? imgId,
    @JsonKey(name: "img_data", fromJson: _fromBase64, toJson: _toBase64)
    Uint8List? img,
    // required double imgSize, // Ensure size is required // I am not using this for the meantime
  }) = _ImageData;

  factory ImageData.fromJson(Map<String, dynamic> json) =>
      _$ImageDataFromJson(json);
}
